"""Independent straightforward reference implementation of the replay engine."""
from math import gcd

PS = 10**6


def calib_ref(profile):
    K = profile['groups']; jit = profile['jitter_ps']; ms = profile['measurements']
    INF = float('inf')
    d = [[INF]*K for _ in range(K)]
    for i in range(K):
        d[i][i] = 0
    for (a, b, L, U) in ms:
        d[a][b] = min(d[a][b], U); d[b][a] = min(d[b][a], -L)
    for k in range(K):
        for i in range(K):
            for j in range(K):
                if d[i][k] + d[k][j] < d[i][j]:
                    d[i][j] = d[i][k] + d[k][j]
    feas = all(d[i][i] >= 0 for i in range(K))
    H = [[0]*K for _ in range(K)]; C = [[0]*K for _ in range(K)]
    if feas:
        for a in range(K):
            for b in range(K):
                hi = d[a][b]; lo = -d[b][a]
                H[a][b] = (hi-lo)*500000 + (jit[a]+jit[b])*PS
                C[a][b] = (lo+hi)*500000
    # a feasible bias vector
    x = [0]*K
    if feas and K:
        for v in range(K):
            x[v] = d[0][v]
    return feas, H, C, x


def replay_ref(profile, fb, g, trace):
    feas, H, C, xbias = calib_ref(profile)
    if not feas:
        return None
    N = fb['n']; T = fb['interval_ns']; S = fb['slice_ns']; O = fb['offset_ns']
    slices = fb['slices']; Q = len(slices); P = (Q*S)//gcd(T, Q*S)
    links = fb['links']
    eff = [[fb['drift_ppb'][i]]*P for i in range(N)]
    for (node, a, b, x) in fb['heat']:
        for p in range(a, b):
            eff[node][p] += x
    anch = [[False]*N for _ in range(P)]
    for (node, a, b) in fb['anchors']:
        for p in range(a, b):
            anch[p][node] = True
    black = [[False]*P for _ in range(len(links))]
    for (l, a, b) in fb['blackouts']:
        for p in range(a, b):
            black[l][p] = True
    R = trace['rounds']
    rates = trace['rates_ppb']
    bias = trace['bias_ps']
    lost = set(trace['lost'])

    def slice_rho(p):
        t = O + p*T
        return (t//S) % Q, t % S

    known = [False]*N
    err = [0]*N
    bnd = [0]*N
    gen = [0]*N
    peak = 0
    always = True
    delivered = stalec = unkc = adoptc = pendingc = 0
    status = [None]*len(trace['sends'])
    states = [None]*len(trace['queries'])
    qmap = {}
    for qi, t in enumerate(trace['queries']):
        qmap.setdefault(t, []).append(qi)
    reb = {}
    for (t, n) in trace['reboots']:
        reb.setdefault(t, []).append(n)
    sends_at = {}
    for idx, s in enumerate(trace['sends']):
        sends_at.setdefault(s[1], []).append((s[0], idx, s[2], s[3]))
    inflight = {}
    for t in range(R+1):
        p = t % P
        if t > 0:
            pp = (t-1) % P
            for i in range(N):
                if known[i]:
                    err[i] += rates[t-1][i]*T
                    bnd[i] += eff[i][pp]*T
                    peak = max(peak, abs(err[i]))
        for i in reb.get(t, []):
            known[i] = False
            gen[i] += 1
        for i in range(N):
            if anch[p][i]:
                known[i] = True; err[i] = 0; bnd[i] = 0
        ad = {}
        for pkt in sorted(inflight.get(t, []), key=lambda z: z[0]):
            (pid, src, dst, ce, cb, gs, gd, sk) = pkt
            delivered += 1
            if gen[src] != gs or gen[dst] != gd:
                stalec += 1; continue
            if not sk:
                unkc += 1; continue
            if dst not in ad or (cb, pid) < (ad[dst][0], ad[dst][1]):
                ad[dst] = (cb, pid, ce)
        for dst in sorted(ad):
            cb, pid, ce = ad[dst]
            if (not known[dst]) or cb < bnd[dst]:
                known[dst] = True; err[dst] = ce; bnd[dst] = cb
                ad[dst] = (cb, pid, ce)
                adoptc += 1
                peak = max(peak, abs(ce))
        adopted_now = {dst: ad[dst][1] for dst in ad if known[dst] and bnd[dst] == ad[dst][0] and err[dst] == ad[dst][2]}
        if not all(known):
            always = False
        if t in qmap:
            st = {"bounds_as": [bnd[i] if known[i] else None for i in range(N)],
                  "errors_as": [err[i] if known[i] else None for i in range(N)],
                  "adopted": [adopted_now.get(i) for i in range(N)],
                  "generations": list(gen)}
            for qi in qmap[t]:
                states[qi] = st
        if t < R:
            sl, rho = slice_rho(p)
            reserved = set()
            for (pid, idx, code, jit) in sorted(sends_at.get(t, [])):
                l = code >> 1
                lk = links[l]
                if l not in slices[sl]:
                    status[idx] = 'not_in_slice'; continue
                if code % 2 == 0:
                    src, dst = lk['ends'][0], lk['ends'][1]
                    delay = lk['delay_ns'][0]; q = lk['defer_rounds'][0]
                else:
                    src, dst = lk['ends'][1], lk['ends'][0]
                    delay = lk['delay_ns'][1]; q = lk['defer_rounds'][1]
                k = -(-delay//T)
                if any(black[l][(t+j) % P] for j in range(k)):
                    status[idx] = 'blackout'; continue
                if rho < g or rho + delay + g > S:
                    status[idx] = 'guard'; continue
                port = (src[0], src[1])
                if port in reserved:
                    status[idx] = 'port_busy'; continue
                reserved.add(port)
                if pid in lost:
                    status[idx] = 'lost'; continue
                status[idx] = 'sent'
                app = t + k + q
                if app > R:
                    pendingc += 1; continue
                gs, gd = gen[src[0]], gen[dst[0]]
                sk = known[src[0]]
                ce = (err[src[0]] if sk else 0) + (bias[dst[2]]-bias[src[2]])*PS + jit - C[src[2]][dst[2]]
                cb = (bnd[src[0]] if sk else 0) + H[src[2]][dst[2]]
                kr = t + k
                part = k*T - delay
                ae = 0; ab = 0
                if part:
                    ae += rates[kr-1][dst[0]]*part
                    ab += eff[dst[0]][(kr-1) % P]*part
                for rr in range(kr, app):
                    ae += rates[rr][dst[0]]*T
                    ab += eff[dst[0]][rr % P]*T
                inflight.setdefault(app, []).append((pid, src[0], dst[0], ce+ae, cb+ab, gs, gd, sk))
    return {"status": "ok", "states": states, "send_status": status,
            "delivered": delivered, "adopted": adoptc, "unknown_payloads": unkc,
            "stale_payloads": stalec, "pending": pendingc,
            "peak_known_abs_as": peak, "always_known": always}
PYEOF
